func (h *UserHandler) GetUser(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name") // SOURCE: 外部输入点1
	result, err := h.Svc.FindUserByName(r.Context(), name)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Write([]byte(result))
}

