<?php
declare(strict_types=1);

namespace Plugin\MineAdmin\AppStore\Service;

use Plugin\MineAdmin\AppStore\Support\PathResolver;

class AppService
{
    public function __construct(private PathResolver $resolver) {}

    public function downloadPackage(array $params): array
    {
        $identifier = (string) ($params['identifier'] ?? '');
        // 防御：入口白名单精确允许集（fullmatch），仅接受字母/数字开头、由字母数字下划线点连字符组成的包名，
        // 任何路径分隔符、空字节或 .. 序列均无法匹配并在下一行抛出异常；原版本可被嵌套绕过的黑名单 str_replace 已整体删除
        if ($identifier === '' || preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/', $identifier) !== 1 || str_contains($identifier, '..')) {
            throw new \InvalidArgumentException('illegal package identifier');
        }
        $path = $this->resolver->resolveDownloadPath($identifier);
        return ['file' => $path];
    }
}

# === file: app/Support/PathResolver.php ===
<?php
declare(strict_types=1);

namespace Plugin\MineAdmin\AppStore\Support;

class PathResolver
{
    private string $baseDir = BASE_PATH . '/runtime/appstore/';

    public function resolveDownloadPath(string $name): string
    {
        // 防御：sink 前独立重复同一白名单校验，覆盖绕过 Service 层直接调用本类的替代通道
        if ($name === '' || preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/', $name) !== 1 || str_contains($name, '..')) {
            throw new \InvalidArgumentException('illegal package identifier');
        }
        // 防御：realpath 归一化 + 基目录前缀强校验，即使白名单日后放宽也不允许逃出基目录
        $baseReal = realpath($this->baseDir);
        if ($baseReal === false) {
            throw new \RuntimeException('appstore base directory missing');
        }
        $full = $this->baseDir . $name;
        $real = realpath($full);
        if ($real === false || !str_starts_with($real, $baseReal . DIRECTORY_SEPARATOR)) {
            throw new \RuntimeException('app package not found');
        }
        if (!is_file($real)) {
            throw new \RuntimeException('app package not found');
        }
        return file_get_contents($real);
    }
}

