    raw_name = request.json.get('artifact', '')
    path = resolve_artifact_path(raw_name)
    return jsonify(service.inspect(path))


@bp.route('/api/models/resave', methods=['POST'])
def resave_model():
    # SOURCE 2/3: two more attacker-controlled names
    raw_name = request.json.get('artifact', '')
    raw_target = request.json.get('target', 'out.weights.h5')
    src = resolve_artifact_path(raw_name)
    dst = resolve_artifact_path(raw_target)
    return jsonify(service.resave(src, dst))

